import gzip,random
from pyliftover import LiftOver

def build_chains(path):
 chains=[]; cur=None
 with gzip.open(path,'rt') as f:
  for raw in f:
   line=raw.rstrip('\\n')
   if not line:
    if cur: chains.append(cur); cur=None
    continue
   if line.startswith('#'): continue
   if line.startswith('chain'):
    p=line.split(); cur={'score':float(p[1]),'tName':p[2],'tSize':int(p[3]),'tStrand':p[4],'tStart':int(p[5]),'tEnd':int(p[6]),'qName':p[7],'qSize':int(p[8]),'qStrand':p[9],'qStart':int(p[10]),'qEnd':int(p[11]),'blocks':[]}
   else:
    p=line.split(); size=int(p[0]); dq=int(p[1]); dt=int(p[2]); cur['blocks'].append((size,dt,dq))
 if cur: chains.append(cur)
 return chains

def lift(chains,chrom,pos):
 q0=pos-1; best=None
 for c in chains:
  if c['qName']"'!=chrom or not(c['"'qStart']<=q0<c['qEnd']): continue
  s=c['qStart']; t=0; mapped=None
  for size,dt,dq in c['blocks']:
   if q0<s+size:
    off=q0-s
    if c['qStrand']=='+':
     if c['tStrand']=='+': mapped=c['tStart']+t+off+1
     else: mapped=c['tEnd']-(t+off)
    else:
     if c['tStrand']=='+': mapped=c['tStart']+t+(size-1-off)+1
     else: mapped=c['tEnd']-(t+(size-1-off))
    break
   s += size+dq; t += size+dt
  if mapped is not None:
   if best is None or c['score']>best[0]: best=(c['score'],mapped)
 return best[1] if best else None
chains=build_chains('/workspace/ref/hg19ToHg38.over.chain.gz')
lo=LiftOver('hg19','hg38')
random.seed(0); sample=random.sample(range(10000,248000000),5000)
mism=0; both=0; customnone=0; plonone=0
