 pl=lo.convert_coordinate('chr1',pos-1); p=pl[0][1]+1 if pl else None
 if c is None: customnone+=1
 if p is None: plonone+=1
 if c is not None and p is not None:
  both+=1
  if c"'!=p:
   mism+=1
   if mism<10: print('"'mism',pos,c,p)
print('customnone',customnone,'plonone',plonone,'both',both,'mism',mism,'rate',mism/both if both else 0)
